<?php
namespace Tivoli\Service;
use RuntimeException;
use Tivoli\Domain\Stay\StayRules as R;

/** All receipt/payout sources, inclusive UTC dates and full-period exact totals, with bounded pages. */
final class FinancePaymentLog
{
    public static function read(AccessService $a,int $actor,array $query):array{
        $a->requirePrivilege($actor,'payments.view');$r=$a->repo;$start=$query['start']??gmdate('Y-m-d',strtotime('monday this week'));$end=$query['end']??gmdate('Y-m-d');
        foreach([$start,$end] as $date){if(!is_string($date))throw new RuntimeException('Invalid payment date.');$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date||$date<'1000-01-01')throw new RuntimeException('Choose valid payment dates.');}if($start>$end)throw new RuntimeException('Start date must not follow end date.');
        $direction=$query['direction']??'all';if(!is_string($direction)||!in_array($direction,['all','incoming','outgoing','transfer','adjustment'],true))throw new RuntimeException('Choose a valid payment direction.');
        $page=filter_var($query['log_page']??'1',FILTER_VALIDATE_INT);if($page===false||$page<1||$page>1000000)throw new RuntimeException('Choose a valid payment page.');
        $salary=in_array('hr.salary',$r->privileges($actor),true);
        $method="CONVERT(p.method USING utf8mb4) COLLATE utf8mb4_unicode_ci";$jsonMethod="COALESCE(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.method')),'momo') COLLATE utf8mb4_unicode_ci";
        $union="SELECT 'guest' source,p.id,p.created_at recorded_at,CAST(p.amount*100 AS SIGNED) amount_minor,$method method,'incoming' direction,s.actor_id,p.booking_id,CONVERT(p.note USING utf8mb4) COLLATE utf8mb4_unicode_ci payload FROM payments p LEFT JOIN stay_receipts s ON s.payment_id=p.id
        UNION ALL SELECT 'income',f.id,f.created_at,f.amount_minor,$jsonMethod,'incoming',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='income_recorded'
        UNION ALL SELECT 'cost',f.id,f.created_at,f.amount_minor,$jsonMethod,'outgoing',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='cost_paid'";
        if(!$salary)$union.=" AND NOT EXISTS(SELECT 1 FROM finance_events q WHERE f.target_type='request' AND CAST(q.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci=f.target_id AND q.kind='payroll_requested')";
        // Historical refund method stays explicitly unknown; new refund annotations identify MoMo.
        $union.=" UNION ALL SELECT 'refund',x.id,x.created_at,x.amount_minor,COALESCE((SELECT JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.method')) FROM finance_events f WHERE f.kind='refund_recorded' AND f.target_type='refund' AND f.target_id=CAST(x.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci ORDER BY f.id DESC LIMIT 1),'unknown'),'outgoing',x.actor_id,x.booking_id,CONVERT(x.proof USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM stay_refunds x
        UNION ALL SELECT 'deposit',f.id,f.created_at,f.amount_minor,'cash_to_momo','transfer',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='deposit_recorded'";
        $adjustments=\Tivoli\Repository\ReceiptAccounting::adjustmentsSql();$union.=" UNION ALL SELECT 'correction',a.id,a.created_at,CAST(a.amount*100 AS SIGNED),a.method,'adjustment',f.actor_id,a.booking_id,f.payload FROM ($adjustments) a JOIN finance_events f ON f.id=a.id";
        $union.=" UNION ALL SELECT 'expense_correction',f.id,f.created_at,CAST(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.paid_delta')) AS SIGNED),CONVERT(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.after.method')) USING utf8mb4) COLLATE utf8mb4_unicode_ci,'adjustment',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='ec_posted' AND f.target_type='expense'";
        $union.=" UNION ALL SELECT 'purchase_correction',f.id,f.created_at,CAST(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.paid_delta')) AS SIGNED),CONVERT(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.payment_method')) USING utf8mb4) COLLATE utf8mb4_unicode_ci,'adjustment',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='pc_posted' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.paid_delta')) AS SIGNED)<>0";
        if($salary)$union.=" UNION ALL SELECT 'payroll_correction',f.id,f.created_at,CAST(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.paid_delta')) AS SIGNED),'momo','adjustment',f.actor_id,NULL,f.payload FROM finance_events f WHERE f.kind='payroll_adjustment' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(f.payload,'$.paid_delta')) AS SIGNED)<>0";
        $from=$start.' 00:00:00';$to=(new \DateTimeImmutable($end))->modify('+1 day')->format('Y-m-d').' 00:00:00';$where=' WHERE z.recorded_at>=? AND z.recorded_at<?';$values=[$from,$to];if($direction==='incoming'){$where.=" AND (z.direction='incoming' OR z.source='correction')";}elseif($direction==='outgoing'){$where.=" AND (z.direction='outgoing' OR z.source IN ('expense_correction','purchase_correction','payroll_correction'))";}elseif($direction!=='all'){$where.=' AND z.direction=?';$values[]=$direction;}
        $sql=' FROM ('.$union.') z'.$where;$totals=$r->run("SELECT COUNT(*) count,COALESCE(SUM(CASE WHEN direction='incoming' THEN amount_minor ELSE 0 END),0) incoming,COALESCE(SUM(CASE WHEN direction='outgoing' THEN amount_minor ELSE 0 END),0) outgoing,COALESCE(SUM(CASE WHEN source='correction' THEN amount_minor ELSE 0 END),0) adjustments,COALESCE(SUM(CASE WHEN source IN ('expense_correction','purchase_correction') THEN amount_minor ELSE 0 END),0) expense_adjustments,COALESCE(SUM(CASE WHEN source='payroll_correction' THEN amount_minor ELSE 0 END),0) payroll_adjustments,COALESCE(SUM(CASE WHEN direction='transfer' THEN amount_minor ELSE 0 END),0) transfers".$sql,$values)->fetch();
        $pages=max(1,intdiv((int)$totals['count']+49,50));$page=min($page,$pages);$offset=($page-1)*50;$rows=$r->run('SELECT z.*'.$sql.' ORDER BY z.recorded_at DESC,z.source,z.id DESC LIMIT 50 OFFSET '.$offset,$values)->fetchAll();
        $owner=(new FinanceService($a))->canPostLate($actor);
        $cursor=(int)$r->run('SELECT payment_cursor FROM finance_schema WHERE id=1')->fetchColumn();
        foreach($rows as &$row){$row['actor_name']=$row['actor_id']?$r->run('SELECT name FROM users WHERE id=?',[$row['actor_id']])->fetchColumn():'Historical Actor Unknown';$row['reference']='';$row['description']='';$row['payer']='';$row['status']='Recorded';
            if($row['source']==='guest'||$row['source']==='refund'){$b=$r->run('SELECT b.guest_name,r.name room FROM bookings b JOIN rooms r ON r.id=b.room_id WHERE b.id=?',[$row['booking_id']])->fetch();$row['payer']=$b['guest_name']??'Historical Guest';$row['description']='Room '.($b['room']??'').' · Guest Stay #'.$row['booking_id'];$row['reference']=$row['source']==='guest'?(string)$r->run('SELECT reference_no FROM stay_receipts WHERE payment_id=?',[$row['id']])->fetchColumn():$row['payload'];if($row['source']==='guest'&&trim($row['reference'])==='')$row['reference']=$row['payload']??'';}
            else{$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$row['reference']=$d['reference']??'';$row['payer']=$d['payer']??$d['destination']??'Business MoMo';$row['description']=$row['source']==='income'?$d['activity']:($row['source']==='cost'?'Cost Settlement':'Internal Cash → MoMo Transfer');if($row['source']==='income')$row['status']=$d['treatment']==='advance'?($r->run("SELECT id FROM finance_events WHERE kind='income_completed' AND target_type='income' AND target_id=?",[(string)$row['id']])->fetchColumn()?'Advance · Service Delivered':'Advance Receipt'):'Completed Service';if($row['source']==='deposit'){$allocationView=\Tivoli\Repository\ReceiptReallocation::event($r,['id'=>$row['id'],'data'=>$d]);$resolution=\Tivoli\Domain\Finance\CashResolution::position('deposit',(int)$row['id'],(int)$row['amount_minor'],\Tivoli\Repository\ReceiptReallocation::events((new FinanceService($a))->events()),$allocationView['data']['allocations']);$row['status']=$resolution['verified']===(int)$row['amount_minor']?'Wallet Confirmed':('Verified GHS '.R::decimal($resolution['verified']).' / Returned GHS '.R::decimal($resolution['returned']).' / In Transit GHS '.R::decimal($resolution['remaining']));}}
            if($row['source']==='correction'){$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$row['reference']=$d['after']['reference'];$row['payer']='Original Guest Receipt #'.$d['payment_id'];$row['description']='Recording Adjustment #'.$row['id'].' / Original Activity '.$d['original_activity_date'];$row['status']='Posted Adjustment - No Money Moved';}
            if($row['source']==='expense_correction'){$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$row['reference']=$d['after']['reference'];$row['payer']='Original Expense #'.$d['expense_id'];$row['description']='Expense Recording Adjustment / Cash '.R::decimal($d['cash_delta']).' / MoMo '.R::decimal($d['momo_delta']).' / Original Activity '.$d['original_activity_date'];$row['status']='Posted Adjustment - No Money Moved';}
            if($row['source']==='purchase_correction'){$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$row['payer']=$d['supplier'];$row['description']='Linked Purchase / Provider Payment Recording Adjustment · Original Activity '.$d['original_activity_date'];$row['status']='Posted Adjustment - No Money Moved';$payload=$r->run('SELECT payload FROM finance_events WHERE id=?',[$d['payment_id']])->fetchColumn();$row['reference']=$payload?(json_decode($payload,true,512,JSON_THROW_ON_ERROR)['reference']??''):'';}
            if($row['source']==='payroll_correction'){$row['payer']='Private Payroll';$row['reference']='Restricted Payroll Reference';$row['description']='Payroll Recording Adjustment';$row['status']='Posted Adjustment - No Money Moved';}
            $row['can_correct']=$row['source']==='guest'&&in_array('bookings.manage',$r->privileges($actor),true)&&($owner||(int)$row['actor_id']===$actor);if($row['source']==='guest')$row['effective']=\Tivoli\Repository\ReceiptAccounting::position($r,(int)$row['id'])['position'];
            $source=match($row['source']){
                'guest'=>(int)$row['id']>$cursor&&($row['effective']['method']??'')==='momo'&&$row['effective']['amount']>0?'payment':null,
                'income'=>$row['method']==='momo'?'income':null,
                default=>null,
            };
            if($source&&$row['actor_id']){
                $canReport=$owner||(int)$row['actor_id']===$actor;
                $caseId=$canReport?CashDiscrepancyService::caseId($r,$source,(int)$row['id']):0;
                if($canReport)$row['difference_query']=['page'=>'discrepancies']+($caseId?['id'=>$caseId]:['type'=>$source,'source_id'=>(int)$row['id']]);
            }
            if($row['source']==='cost'&&isset($d['payroll_id'])&&(new FinanceService($a))->canPostLate($actor)&&$salary){$private=(new PayrollService($a))->paymentReference($actor,(int)$d['payroll_id'],(int)$row['id']);if($private){$row['reference']=$private['reference'];$row['payer']=$private['staff_name'];$row['description']='Payroll Settlement · Actual Transfer '.\display_date($private['paid_at']).' UTC';}}
        }unset($row);$a->audit($actor,'finance.payment_log_viewed','finance',null,'succeeded',['start'=>$start,'end'=>$end,'direction'=>$direction,'page'=>$page,'rows'=>count($rows),'payroll_visible'=>$salary]);return compact('rows','totals','page','pages','start','end','direction');
    }
}
